// HasAttempts applies the HasEdge predicate on the "attempts" edge.
func HasAttempts() predicate.GatewayCall {
	return predicate.GatewayCall(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.O2M, false, AttemptsTable, AttemptsColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasAttemptsWith applies the HasEdge predicate on the "attempts" edge with a given conditions (other predicates).
func HasAttemptsWith(preds ...predicate.GatewayCallAttempt) predicate.GatewayCall {
	return predicate.GatewayCall(func(s *sql.Selector) {
		step := newAttemptsStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// HasMonitoredInput applies the HasEdge predicate on the "monitored_input" edge.
func HasMonitoredInput() predicate.GatewayCall {
	return predicate.GatewayCall(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.O2O, false, MonitoredInputTable, MonitoredInputColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasMonitoredInputWith applies the HasEdge predicate on the "monitored_input" edge with a given conditions (other predicates).
func HasMonitoredInputWith(preds ...predicate.MonitoredInput) predicate.GatewayCall {
	return predicate.GatewayCall(func(s *sql.Selector) {
		step := newMonitoredInputStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.GatewayCall) predicate.GatewayCall {
	return predicate.GatewayCall(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.GatewayCall) predicate.GatewayCall {
	return predicate.GatewayCall(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.GatewayCall) predicate.GatewayCall {
	return predicate.GatewayCall(sql.NotPredicates(p))
}
